package com.discordscreenshot;

import net.runelite.client.config.*;
import java.awt.*;

@ConfigGroup("discord-screenshot")
public interface DiscordScreenshotConfig extends Config
{
	@ConfigSection(
			name = "Discord Screenshot Settings",
			description = "General settings.",
			position = 0,
			closedByDefault = false
	)
	String DiscordConfig = "DiscordConfig";

	@ConfigItem(
			keyName = "screenshot",
			name = "Save Screenshot",
			description = "Saves screenshot locally.",
			section = DiscordConfig,
			position = 1
	)
	default boolean saveScreenshot() { return true; }

	@ConfigItem(
			keyName = "showSidebar",
			name = "Show Sidebar",
			description = "Shows the Discord Screenshot tab in the RuneLite sidebar, used to add, rename and delete webhooks. The Discord icon in the top bar keeps working when this is off.",
			section = DiscordConfig,
			position = 2
	)
	default boolean showSidebar()
	{
		return true;
	}

	@ConfigItem(
			keyName = "hideChat",
			name = "Hide Chat",
			description = "Hides the chat box from the screenshot.",
			section = DiscordConfig,
			position = 3
	)
	default boolean hideChat() { return false; }

	@ConfigItem(
			keyName = "hidePrivate",
			name = "Hide PMs",
			description = "Hides the private message popups from the screenshot.",
			section = DiscordConfig,
			position = 4
	)
	default boolean hidePrivate() { return true; }


	@ConfigItem(
			keyName = "soundScreenshot",
			name = "Make Sound",
			description = "Make sound when screenshot taken.",
			section = DiscordConfig,
			position = 5
	)
	default boolean soundScreenshot() { return true; }

	@Range(min = 1, max = 100)
	@ConfigItem(
			keyName = "volumeSound",
			name = "Volume",
			description = "Screenshot sound effect volume",
			section = DiscordConfig,
			position = 6
	)
	default int volumeSound() { return 70; }

	@ConfigItem(
			keyName = "hotkey",
			name = "Default Webhook Hotkey",
			description = "Set a hotkey for taking a screenshot & sending to discord.",
			section = DiscordConfig,
			position = 7
	)
	default Keybind hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigSection(
			name = "Default Webhook",
			description = "The config for webhook content notifications",
			position = 1,
			closedByDefault = false
	)
	String DiscordHookConfig = "DiscordHookConfig";

	@ConfigItem(
			keyName = "disclaimer",
			name = "Hover here for more info",
			description = "Left-clicking the Discord Screenshot icon sends to this webhook. More webhooks: open the Discord Screenshot tab in the sidebar, then right-click the icon to pick one.",
			section = DiscordHookConfig,
			position = 1
	)
	default void disclaimer() {}

	@ConfigItem(
			keyName = "webhook",
			secret = true,
			name = "Webhook URL",
			description = "The Discord Webhook URL to send messages to.",
			section = DiscordHookConfig,
			position = 2
	)
	String webhook();

	@ConfigSection(
			name = "Overlay Settings",
			description = "Custom Overlay",
			position = 2,
			closedByDefault = true
	)
	String OverlayConfig = "OverlayConfig";

	@ConfigItem(
			keyName = "overlay",
			name = "Display Overlay",
			description = "Displays the custom overlay on your game screen.",
			section = OverlayConfig,
			position = 1
	)
	default boolean overlay()
	{
		return false;
	}

	@ConfigItem(
			keyName = "dateTime",
			name = "Date & Time",
			description = "Adds the date and time to the custom overlay.",
			section = OverlayConfig,
			position = 2
	)
	default boolean dateTime()
	{
		return true;
	}

	@ConfigItem(
			keyName = "customText",
			name = "Custom Text",
			description = "Adds the text to the custom overlay.",
			section = OverlayConfig,
			position = 3
	)
	default String customText()
	{
		return "";
	}

	@Range(min = 10, max = 100)
	@ConfigItem(
			keyName = "textWidth",
			name = "Text Width",
			description = "Space width between custom text and date & time.",
			section = OverlayConfig,
			position = 4
	)
	default int textWidth() { return 10; }

	@ConfigItem(
			keyName = "TextColor",
			name = "Text Color",
			description = "Configure the color of the custom overlay text.",
			section = OverlayConfig,
			position = 5
	)
	default Color textColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
			keyName = "dateTimeColor",
			name = "Date & time Color",
			description = "Configure the color of date & time",
			section = OverlayConfig,
			position = 6
	)
	default Color dateTimeColor()
	{
		return Color.YELLOW;
	}
}

package com.discordscreenshot;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

public class DiscordScreenshotOverlay extends OverlayPanel
{
	private static final DateTimeFormatter FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");

	private final DiscordScreenshotConfig config;

	@Inject
	private DiscordScreenshotOverlay(DiscordScreenshotConfig config)
	{
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
	}

	static String utcTime()
	{
		return FORMAT.format(ZonedDateTime.now(ZoneOffset.UTC)) + " UTC";
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final String customText = config.customText() == null ? "" : config.customText().trim();
		if (!config.overlay() || customText.isEmpty())
		{
			return null;
		}

		final LineComponent.LineComponentBuilder line = LineComponent.builder()
			.left(customText)
			.leftColor(config.textColor());

		String measured = customText;
		if (config.dateTime())
		{
			final String time = utcTime();
			line.right(time).rightColor(config.dateTimeColor());
			measured = customText + " " + time;
		}

		panelComponent.getChildren().add(line.build());
		panelComponent.setPreferredSize(new Dimension(
			graphics.getFontMetrics().stringWidth(measured) + config.textWidth(), 0));

		return super.render(graphics);
	}
}

package com.discordscreenshot;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
